import numpy as np

class CrossValidationVisualization(Scene):
    def construct(self):
        title = Text("Cross-Validation & Hyperparameter Tuning", font_size=34).to_edge(UP, buff=0.6)
        self.play(Write(title))

        k = 5
        folds = VGroup(*[
            Rectangle(width=1.0, height=0.7, color=BLUE).move_to(np.array([(i - (k-1)/2) * 1.3, 0.6, 0]))
            for i in range(k)
        ])
        fold_labels = VGroup(*[
            Text(f"Fold {i+1}", font_size=22).move_to(folds[i].get_center())
            for i in range(k)
        ])

        self.play(LaggedStart(*[Create(f) for f in folds], lag_ratio=0.12))
        self.play(LaggedStart(*[Write(lbl) for lbl in fold_labels], lag_ratio=0.12))

        hp_candidates = [0.01, 0.1, 1, 10]
        hp_boxes = VGroup(*[
            Rectangle(width=0.9, height=0.6, color=GRAY).move_to(np.array([(-1.5 + j*1.2), -1.3, 0]))
            for j in range(len(hp_candidates))
        ])
        hp_labels = VGroup(*[
            Text(f"C={v}", font_size=20).move_to(hp_boxes[j].get_center())
            for j, v in enumerate(hp_candidates)
        ])

        self.play(LaggedStart(*[Create(b) for b in hp_boxes], lag_ratio=0.12))
        self.play(LaggedStart(*[Write(l) for l in hp_labels], lag_ratio=0.12))

        scores = [round(np.random.uniform(0.70, 0.92), 3) for _ in hp_candidates]
        score_texts = [MathTex(str(s)).next_to(hp_boxes[j], DOWN, buff=0.15) for j, s in enumerate(scores)]

        for j in range(len(hp_candidates)):
            self.play(Write(score_texts[j]))

        best_idx = int(np.argmax(scores))
        best_box = SurroundingRectangle(hp_boxes[best_idx], color=GREEN, buff=0.12)
        self.play(Create(best_box))
        self.wait(1.5)

