class ForwardPropagation(Scene):
    def construct(self):
        title = Text("Forward Propagation", font_size=36).to_edge(UP)
        self.play(Write(title))
        self.wait(0.4)

        input_layer = VGroup(*[Dot(color=BLUE) for _ in range(3)]).arrange(DOWN, buff=0.4)
        hidden_layer = VGroup(*[Dot(color=GREEN) for _ in range(4)]).arrange(DOWN, buff=0.4)
        output_layer = VGroup(*[Dot(color=RED) for _ in range(2)]).arrange(DOWN, buff=0.4)

        layers = VGroup(input_layer, hidden_layer, output_layer).arrange(RIGHT, buff=2).shift(DOWN)
        self.play(FadeIn(layers))

        for i in input_layer:
            for h in hidden_layer:
                self.add(Line(i.get_center(), h.get_center(), stroke_width=1))
        for h in hidden_layer:
            for o in output_layer:
                self.add(Line(h.get_center(), o.get_center(), stroke_width=1))

        self.wait(2)
